package com.byawasaya.platform.orders;

import java.math.BigDecimal; import java.time.Instant; import java.util.List; import java.util.UUID;
import com.byawasaya.platform.catalog.SalesType;
import jakarta.validation.Valid; import jakarta.validation.constraints.Email; import jakarta.validation.constraints.Max; import jakarta.validation.constraints.Min; import jakarta.validation.constraints.NotBlank; import jakarta.validation.constraints.NotEmpty; import jakarta.validation.constraints.NotNull; import jakarta.validation.constraints.Size;
public final class OrderDtos {
 private OrderDtos(){}
 public record OrderLineRequest(@NotNull UUID productId,UUID variantId,@Min(1) @Max(999) int quantity){public OrderLineRequest(UUID productId,int quantity){this(productId,null,quantity);}}
 public record CreateOrderRequest(@NotBlank @Size(max=120) String customerName,@NotBlank @Size(max=30) String phone,@Email @Size(max=180) String email,@NotBlank @Size(max=100) String province,@NotBlank @Size(max=100) String district,@Size(max=120) String municipality,@Size(max=10) String ward,@NotBlank @Size(max=300) String addressLine,@NotNull SalesType salesType,@NotNull PaymentMethod paymentMethod,com.byawasaya.platform.payments.PaymentProvider paymentProvider,@Size(max=500) String customerNote,@NotEmpty List<@Valid OrderLineRequest> items){public CreateOrderRequest(String customerName,String phone,String email,String province,String district,String municipality,String ward,String addressLine,SalesType salesType,PaymentMethod paymentMethod,String customerNote,List<OrderLineRequest> items){this(customerName,phone,email,province,district,municipality,ward,addressLine,salesType,paymentMethod,null,customerNote,items);}}
 public record OrderItemResponse(UUID productId,UUID variantId,String variantLabel,String productName,String sku,int quantity,BigDecimal unitPrice,BigDecimal lineTotal){}
 public record OrderResponse(UUID id,String orderNumber,String customerName,String phone,String email,String province,String district,String municipality,String addressLine,SalesType salesType,PaymentMethod paymentMethod,PaymentStatus paymentStatus,OrderStatus status,BigDecimal subtotal,BigDecimal deliveryFee,BigDecimal advanceAmount,BigDecimal totalAmount,String customerNote,Instant createdAt,List<OrderItemResponse> items){public static OrderResponse from(CustomerOrder o){return new OrderResponse(o.getId(),o.getOrderNumber(),o.getCustomerName(),o.getPhone(),o.getEmail(),o.getProvince(),o.getDistrict(),o.getMunicipality(),o.getAddressLine(),o.getSalesType(),o.getPaymentMethod(),o.getPaymentStatus(),o.getStatus(),o.getSubtotal(),o.getDeliveryFee(),o.getAdvanceAmount(),o.getTotalAmount(),o.getCustomerNote(),o.getCreatedAt(),o.getItems().stream().map(i->new OrderItemResponse(i.getProductId(),i.getVariantId(),i.getVariantLabel(),i.getProductName(),i.getSku(),i.getQuantity(),i.getUnitPrice(),i.getLineTotal())).toList());}}
 public record UpdateOrderStatusRequest(@NotNull OrderStatus status){}
 public record UpdatePaymentStatusRequest(@NotNull PaymentStatus status){}
}
